window.addEventListener("keydown", (event) => {
  const tag = document.activeElement?.tagName?.toLowerCase();
  let editingField = tag === "input"
    || tag === "textarea"
    || tag === "select"
    || document.activeElement?.isContentEditable;
  if (focusedControlShouldYieldToShortcut(document.activeElement, event)) {
    document.activeElement.blur();
    editingField = false;
  }
  if (event.key === "Shift" && !event.repeat) {
    transformPrecisionHeld = true;
    syncNavigationModifierLocks();
  }
  if (event.key === "Control" && !event.repeat) {
    selectionRemoveHeld = true;
    syncNavigationModifierLocks();
  }
  if (event.key === "Escape" && finishReferenceOverlayDrag(event, { cancel: true })) {
    event.preventDefault();
    return;
  }
  if (event.key === "Escape" && proceduralDuplicateDialog.open) {
    closeProceduralDuplicateDialog();
    event.preventDefault();
    return;
  }
  if (event.key === "Escape" && cancelDuplicatePlacement()) {
    event.preventDefault();
    return;
  }
  if (event.key === "Escape" && cancelStrandRadialGesture()) {
    event.preventDefault();
    return;
  }
  if (event.key === "Escape" && cancelToolShortcutPress()) {
    event.preventDefault();
    return;
  }
  if (
    event.key === "Escape"
    && activeTool === "poly"
    && polyBrushStroke
  ) {
    finishPolyBrushStroke(event, { cancel: true });
    event.preventDefault();
    return;
  }
  if (event.key === "Escape" && activeTool === "draw-capsule-guide" && capsuleGuideDrawStroke) {
    finishCapsuleGuideDrawStroke(event, { cancel: true });
    event.preventDefault();
    return;
  }
  if (event.key === "Escape" && activeTool === "surface-loft" && cancelLoftSurfaceDraft()) {
    event.preventDefault();
    resetLoftSurfaceDraft();
    return;
  }
  if (event.key === "Escape" && activeTool === "curve-surface" && curveSurfaceDraft) {
    if (curveSurfaceDraft.activeStroke) finishCurveSurfaceStroke(event, { cancel: true });
    else cancelCurveSurfaceDraft();
    event.preventDefault();
    return;
  }
  if (!editingField && event.key === "Enter" && activeTool === "curve-surface" && commitCurveSurfaceDraft(event)) {
    event.preventDefault();
    return;
  }
  const requestedShortcutTool = !editingField && !event.ctrlKey && !event.metaKey && !event.altKey
    ? shortcutToolForKey(event.key)
    : null;
  if (requestedShortcutTool && !event.repeat) {
    cancelStrandRadialGesture();
    cancelToolShortcutPress();
    cancelToolRadialGesture();
  }
  if (duplicatePlacement) {
    event.preventDefault();
    return;
  }
  if (toolRadialGesture) {
    event.preventDefault();
    return;
  }
  if (
    !editingField
    && event.ctrlKey
    && !event.metaKey
    && !event.shiftKey
    && !event.altKey
    && event.key === "1"
    && (strandIsolationActive() || selectedLocksInOrder().length)
  ) {
    event.preventDefault();
    if (!event.repeat) toggleSelectedStrandIsolation();
    return;
  }
  if (
    !editingField
    && event.ctrlKey
    && !event.metaKey
    && !event.shiftKey
    && !event.altKey
    && event.key.toLowerCase() === "d"
  ) {
    event.preventDefault();
    if (!event.repeat) duplicateCurrentSelection();
    return;
  }
  if (
    !editingField
    && event.ctrlKey
    && !event.metaKey
    && !event.shiftKey
    && !event.altKey
    && event.key.toLowerCase() === "h"
  ) {
    event.preventDefault();
    if (!event.repeat) {
      if (selectedLocksInOrder().length) hideSelectedStrands();
      else unhideHiddenStrands();
    }
    return;
  }
  if (
    event.key === "Shift"
    && !event.repeat
    && transformDragging
    && ["translate", "rotate", "scale"].includes(transformControls.mode)
  ) {
    event.preventDefault();
    return;
  }
  if (
    navigationStyle === "anime-hair-studio"
    && event.key === "Shift"
    && !event.repeat
    && beginViewSnapFromActiveOrbit()
  ) {
    event.preventDefault();
    return;
  }
  if (
    navigationStyle === "blender"
    && event.key === "Alt"
    && !event.repeat
    && beginViewSnapFromActiveOrbit()
  ) {
    event.preventDefault();
    return;
  }
  if (
    navigationStyle === "blender"
    && event.key === "Shift"
    && activeViewportPointer?.buttonMask === 4
    && (activeViewportPointer.buttons & 4)
  ) {
    event.preventDefault();
    return;
  }
  if (event.key === "Shift" && !event.repeat && !editingField && sculptBrushToolActive()) {
    setSculptBrushShiftSmoothHeld(true);
  }
  if (event.key === "Shift" && !event.repeat && !editingField && activeTool === "poly") {
    polyShiftPreviewHeld = true;
    refreshPolyFillPreviewFromLastPointer();
  }
  if (event.key === "Escape" && !presetLibrary.classList.contains("hidden")) {
    event.preventDefault();
    setPresetLibraryOpen(false);
    presetLibraryToggle.focus();
    return;
  }
  if (!editingField && (event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "z" && !event.shiftKey) {
    event.preventDefault();
    if (event.repeat || historyShortcutHeld) return;
    historyShortcutHeld = true;
    undoLastAction();
    return;
  }
  if (
    !editingField
    && (event.ctrlKey || event.metaKey)
    && (event.key.toLowerCase() === "y" || (event.shiftKey && event.key.toLowerCase() === "z"))
  ) {
    event.preventDefault();
    if (event.repeat || historyShortcutHeld) return;
    historyShortcutHeld = true;
    redoLastAction();
    return;
  }
  if (
    !editingField
    && !event.ctrlKey
    && !event.metaKey
    && !event.altKey
    && event.key.toLowerCase() === "z"
    && activeTool === "move"
    && viewPlaneMoveActiveForView()
  ) {
    event.preventDefault();
    if (!event.repeat) setViewPlaneNormalMoveHeld(true);
    return;
  }
  if (editingField || event.ctrlKey || event.metaKey || event.altKey) return;
  if (event.key.toLowerCase() === "l") {
    event.preventDefault();
    if (!event.repeat) {
      if (selectedLocksInOrder().length) lockSelectedStrands();
      else unlockAllStrands();
    }
    return;
  }
  if (event.key === "Tab" && !event.shiftKey) {
    event.preventDefault();
    if (!event.repeat) {
      setViewportSelectionMode(effectiveViewportSelectionMode() === "component" ? "object" : "component");
    }
    return;
  }
  const shortcutWorkspace = workspaceForShortcutKey(event.key);
  if (shortcutWorkspace) {
    event.preventDefault();
    if (!event.repeat) setViewportEditMode(shortcutWorkspace);
    return;
  }
  if (event.key === "Delete") {
    event.preventDefault();
    if (!event.repeat) deleteCurrentSelection();
    return;
  }
  if (event.code === "Space") {
    event.preventDefault();
    if (!event.repeat) beginStrandRadialGesture();
    return;
  }
  if (event.key.toLowerCase() === "s") {
    event.preventDefault();
    if (!event.repeat) brushSizeHotkeyHeld = true;
    return;
  }
  if (event.key.toLowerCase() === "b") {
    event.preventDefault();
    if (event.repeat || proportionalHotkeyPress) return;
    proportionalHotkeyPress = {
      wasEnabled: proportionalEditing,
      activatedByHold: false,
      startX: lastPointer.x,
      startY: lastPointer.y,
      holdTimer: null
    };
    if (proportionalEditing) beginProportionalSizeEdit(event);
    else proportionalHotkeyPress.holdTimer = window.setTimeout(activateProportionalHotkeyHold, 180);
    updateInteractionLocks();
    return;
  }
  if (event.key.toLowerCase() === "o") {
    event.preventDefault();
    setObjectSpaceEditing(!objectSpaceEditing);
    return;
  }
  if (event.key.toLowerCase() === "h") {
    event.preventDefault();
    setHierarchyEditing(!hierarchyEditing);
    return;
  }
  if (event.key.toLowerCase() === "f") {
    event.preventDefault();
    if (!event.repeat) cycleViewportFraming();
    return;
  }
  if (event.key.toLowerCase() === "x") {
    event.preventDefault();
    if (!event.repeat) setMirrorXEditing(!mirrorXEditing);
    return;
  }
  const tool = shortcutToolForKey(event.key);
  if (!tool) return;
  event.preventDefault();
  if (event.repeat) return;
  if (hotkeyToolSettingsExperimentalEnabled || ["select", "move", "rotate", "scale"].includes(tool)) {
    beginToolShortcutPress(event.key.toLowerCase(), tool);
  } else {
    setActiveTool(tool);
  }
}, true);

window.addEventListener("keyup", (event) => {
  if (event.key.toLowerCase() === "z") {
    setViewPlaneNormalMoveHeld(false);
  }
  if (event.key === "Shift") {
    transformPrecisionHeld = false;
    syncNavigationModifierLocks();
    setSculptBrushShiftSmoothHeld(false);
    polyShiftPreviewHeld = false;
    clearPolyFillPreview();
    if (navigationStyle === "anime-hair-studio") endViewSnap();
  }
  if (event.key === "Control") {
    selectionRemoveHeld = false;
    syncNavigationModifierLocks();
  }
  if (event.key === "Alt" && navigationStyle === "blender") {
    endViewSnap();
  }
  if (finishToolShortcutPress(event.key.toLowerCase())) {
    event.preventDefault();
  }
  if (event.code === "Space") {
    event.preventDefault();
    finishStrandRadialGesture();
  }
  if (event.key.toLowerCase() === "s") {
    brushSizeHotkeyHeld = false;
  }
  if (event.key.toLowerCase() === "b" && proportionalHotkeyPress) {
    const press = proportionalHotkeyPress;
    window.clearTimeout(press.holdTimer);
    const resizedInfluence = Boolean(proportionalSizeEdit?.didDrag);
    proportionalHotkeyPress = null;
    endProportionalSizeEdit();
    if (!resizedInfluence && !press.activatedByHold) setProportionalEditing(!press.wasEnabled);
    else updateInteractionLocks();
  }
});
window.addEventListener("blur", () => {
  transformPrecisionHeld = false;
  selectionRemoveHeld = false;
  setViewPlaneNormalMoveHeld(false);
  syncNavigationModifierLocks();
  activeViewportPointer = null;
  pointRemovalCandidate = null;
  polyShiftPreviewHeld = false;
  clearPolyFillPreview();
  finishReferenceOverlayDrag(null, { cancel: true });
  cancelStrandRadialGesture();
  cancelToolShortcutPress();
  cancelDuplicatePlacement();
  brushSizeHotkeyHeld = false;
  setSculptBrushShiftSmoothHeld(false);
  finishBrushSizeDrag();
  window.clearTimeout(proportionalHotkeyPress?.holdTimer);
  proportionalHotkeyPress = null;
  endProportionalSizeEdit();
  endViewSnap();
  endViewPlaneMove();
  finishDrawStrandStroke(null, { cancel: true });
  proceduralAccessoryEditPointerActive = false;
  proceduralAccessoryEditHistoryOpen = false;
  finishPolyBrushStroke(null, { cancel: true });
  polyAltDeleteCandidate = null;
  updateInteractionLocks();
});

function deleteLocks(targetLocks) {
  const targets = [...new Set(targetLocks)].filter((lock) => locks.includes(lock));
  if (!targets.length) return;
  const targetIds = new Set(targets.map((lock) => lock.id));
  const branchKnifeParentsToRefresh = new Set(
    targets
      .map((lock) => locks.find((item) => item.id === lock.branchParentId))
      .filter((parent) => parent && !targetIds.has(parent.id))
  );
  targetIds.forEach((id) => selectedStrandIds.delete(id));
  targets.forEach((lock) => {
    const partner = mirrorPartnerFor(lock);
    if (partner && !targetIds.has(partner.id) && partner.mirrorPartnerId === lock.id) {
      partner.mirrorPartnerId = null;
    }
  });
  targets.forEach((item) => {
    if (item.clumpGuide) dissolveClump(item.clumpId);
    else if (item.clumpId) detachLockFromClump(item);
  });
  targets.forEach((parent) => {
    branchChildrenFor(parent).forEach((child) => {
      if (!targetIds.has(child.id)) detachBranch(child);
    });
  });
  if (targets.some((item) => item.curveObjects?.handles.includes(transformControls.object))) transformControls.detach();
  if (targets.some((item) => item.curveObjects?.surfaceObjectAnchor === transformControls.object)) transformControls.detach();
  if (targets.some((item) => selectedPoint?.lockId === item.id)) {
    selectedPoint = null;
    updateSelectedPointLabel();
  }
  if (targets.some((item) => selectedSurfaceObjectAnchorId === item.id)) {
    selectedSurfaceObjectAnchorId = null;
    activeSurfaceObjectTransform = null;
    updateSelectedPointLabel();
  }
  targets.forEach((item) => {
    curveSurfaceOpen.delete(item.id);
    hairGroup.remove(item.mesh);
    curveGroup.remove(item.curveObjects.group);
    item.mesh.geometry.dispose();
    removeUvCheckerFromLock(item);
    item.mesh.material.dispose();
    item.selectionOutline?.material.dispose();
    disposeBranchKnifeOverlay(item.wireOverlay);
    item.wireOverlay?.geometry.dispose();
    item.wireOverlay?.material.dispose();
    disposeCurveObjects(item);
    locks.splice(locks.indexOf(item), 1);
  });
  branchKnifeParentsToRefresh.forEach((parent) => {
    if (locks.includes(parent)) rebuildLockGeometry(parent, {
      updateBranches: false,
      updateBranchKnifeParent: false
    });
  });
  cleanSelectionSets();
  if (isolatedStrandIds) {
    targetIds.forEach((id) => isolatedStrandIds.delete(id));
    if (!isolatedStrandIds.size) isolatedStrandIds = null;
  }
  if (targets.some((item) => item.id === selectedId)) {
    selectedCurveSurfaceController = null;
    const fallback = locks.find((lock) => selectedStrandIds.has(lock.id)) || locks.at(-1);
    if (fallback) selectLock(fallback.id, {
      individualClumpMember: true,
      selectedIds: selectedStrandIds.size ? [...selectedStrandIds] : undefined
    });
    else deselectStrands();
  }
  applyStrandDisplayVisibility();
  renderLockList();
  updateCount();
  requestShadowMapRefresh();
}

document.querySelector("#deleteLock").addEventListener("click", () => {
  deleteSelectedStrands();
});

function disposeCurveObjects(lock) {
  if (!lock.curveObjects) return;
  lock.curveObjects.line.geometry.dispose();
  lock.curveObjects.line.material.dispose();
  lock.curveObjects.handles.forEach((handle) => {
    handle.geometry.dispose();
    handle.material.dispose();
  });
  lock.curveObjects.arrows.forEach((arrow) => {
    arrow.children.forEach((part) => {
      part.geometry?.dispose();
      part.material?.dispose();
    });
  });
  lock.curveObjects.panelSplitHandles?.forEach((handle) => {
    handle.geometry.dispose();
    handle.material.dispose();
  });
  lock.curveObjects.panelSplitLines?.forEach((line) => {
    line.geometry.dispose();
    line.material.dispose();
  });
  lock.curveObjects.compoundBridgeHandles?.forEach((handle) => {
    handle.geometry.dispose();
    handle.material.dispose();
  });
  lock.curveObjects.compoundBridgeLines?.forEach((line) => {
    line.geometry.dispose();
    line.material.dispose();
  });
  if (lock.curveObjects.strandSplitHandle) {
    lock.curveObjects.strandSplitHandle.geometry.dispose();
    lock.curveObjects.strandSplitHandle.material.dispose();
  }
  if (lock.curveObjects.strandSplitLine) {
    lock.curveObjects.strandSplitLine.geometry.dispose();
    lock.curveObjects.strandSplitLine.material.dispose();
  }
  if (lock.curveObjects.surfaceObjectAnchorHandle) {
    lock.curveObjects.surfaceObjectAnchorHandle.geometry.dispose();
    lock.curveObjects.surfaceObjectAnchorHandle.material.dispose();
  }
  if (lock.curveObjects.surfaceObjectAnchorStem) {
    lock.curveObjects.surfaceObjectAnchorStem.geometry.dispose();
    lock.curveObjects.surfaceObjectAnchorStem.material.dispose();
  }
  [
    ...(lock.curveObjects.widthEdgeLines || []),
    ...(lock.curveObjects.depthEdgeLines || []),
    ...(lock.curveObjects.uniformEdgeLines || [])
  ].forEach((edge) => {
    edge.geometry.dispose();
    edge.material.dispose();
  });
  lock.curveObjects.edgePickers?.forEach((edge) => {
    edge.geometry.dispose();
    edge.material.dispose();
  });
}

function beginPanelSplitHandleDrag(event) {
  if (event.button !== 0 || event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) return false;
  const lock = getSelectedLock();
  const panelHandles = isPanelGeometry(lock) && lock.curveObjects?.group.visible
    ? lock.curveObjects.panelSplitHandles || []
    : [];
  const strandHandle = lock?.geometryType === "strand"
    && lock.strandSplitEnabled
    && lock.curveObjects?.group.visible
    && lock.curveObjects.strandSplitHandle?.visible
    ? [lock.curveObjects.strandSplitHandle]
    : [];
  const compoundHandles = lock?.geometryType === "curve-surface"
    && lock.curveSurfaceCompoundProfile
    && lock.curveObjects?.group.visible
    ? lock.curveObjects.compoundBridgeHandles || []
    : [];
  const handles = [...panelHandles, ...strandHandle, ...compoundHandles];
  if (!handles.length) return false;
  const hit = raycaster.intersectObjects(handles.filter((handle) => handle.visible), false)[0];
  if (!hit) return false;
  pushUndoState();
  transformControls.detach();
  const kind = hit.object.userData.strandSplitHandle
    ? "strand"
    : Number.isInteger(hit.object.userData.compoundBridgeIndex)
      ? "compound"
      : "panel";
  const splitIndex = hit.object.userData.compoundBridgeIndex ?? hit.object.userData.panelSplitIndex;
  panelSplitDrag = {
    pointerId: event.pointerId,
    lockId: lock.id,
    kind,
    splitIndex,
    compoundContext: kind === "compound"
      ? createCompoundBridgeControlContext(lock, splitIndex)
      : null
  };
  renderer.domElement.setPointerCapture?.(event.pointerId);
  renderer.domElement.style.cursor = "grabbing";
  updateCurveObjects(lock, { visible: true });
  updateInteractionLocks();
  return true;
}

function updatePanelSplitHandleDrag(event) {
  if (!panelSplitDrag || event.pointerId !== panelSplitDrag.pointerId) return;
  const lock = locks.find((item) => item.id === panelSplitDrag.lockId);
  if (!lock) {
    endPanelSplitHandleDrag(event);
    return;
  }
  const rect = renderer.domElement.getBoundingClientRect();
  const targetX = event.clientX - rect.left;
  const targetY = event.clientY - rect.top;
  const curve = strandGeometryCurve(lock);
  let best = null;
  if (panelSplitDrag.kind === "compound") {
    const seamCount = Math.max(0, Number(lock.curveSurfaceColumns || 0) - 1);
    const seamIndex = THREE.MathUtils.clamp(panelSplitDrag.splitIndex, 0, Math.max(0, seamCount - 1));
    const context = panelSplitDrag.compoundContext
      || createCompoundBridgeControlContext(lock, seamIndex);
    if (!context) return;
    let parameterMin = 0.05;
    let parameterMax = 0.9;
    let offsetMin = -0.35;
    let offsetMax = 0.35;
    for (let pass = 0; pass < 2; pass += 1) {
      const divisions = pass === 0 ? 10 : 6;
      const parameterStep = (parameterMax - parameterMin) / divisions;
      const offsetStepSize = (offsetMax - offsetMin) / divisions;
      let passBest = null;
      for (let tStep = 0; tStep <= divisions; tStep += 1) {
        const parameter = THREE.MathUtils.lerp(parameterMin, parameterMax, tStep / divisions);
        for (let offsetStep = 0; offsetStep <= divisions; offsetStep += 1) {
          const offset = THREE.MathUtils.lerp(offsetMin, offsetMax, offsetStep / divisions);
          const projected = compoundBridgeControlPoint(
            lock,
            seamIndex,
            parameter,
            offset,
            context
          ).project(camera);
          if (projected.z < -1 || projected.z > 1) continue;
          const x = (projected.x * 0.5 + 0.5) * rect.width;
          const y = (-projected.y * 0.5 + 0.5) * rect.height;
          const distanceSq = (x - targetX) ** 2 + (y - targetY) ** 2;
          if (!passBest || distanceSq < passBest.distanceSq) {
            passBest = { distanceSq, parameter, offset };
          }
        }
      }
      if (!passBest) break;
      best = passBest;
      parameterMin = Math.max(0.05, best.parameter - parameterStep);
      parameterMax = Math.min(0.9, best.parameter + parameterStep);
      offsetMin = Math.max(-0.35, best.offset - offsetStepSize);
      offsetMax = Math.min(0.35, best.offset + offsetStepSize);
    }
    if (!best) return;
    const renderSegments = THREE.MathUtils.clamp(
      Math.max(
        Math.round(Number(lock.lengthSegments) || 26),
        Math.round(Number(lock.curveSurfaceRows) || DEFAULT_CURVE_SURFACE_ROWS) - 1
      ),
      4,
      256
    );
    const zippers = normalizeCompoundBridgeZippers(lock.compoundBridgeZippers, seamCount);
    zippers[seamIndex] = {
      parameter: THREE.MathUtils.clamp(
        Math.round(best.parameter * renderSegments) / renderSegments,
        0.05,
        0.9
      ),
      offset: THREE.MathUtils.clamp(best.offset, -0.35, 0.35)
    };
    lock.compoundBridgeZippers = zippers;
    updateLockGeometry(lock, { defer: true });
    updateCurveObjects(lock, { visible: true });
    syncActiveMirror(lock, { deferGeometry: true });
    event.preventDefault();
    return;
  }
  if (panelSplitDrag.kind === "strand") {
    const profileData = strandSplitProfileData(lock);
    for (let tStep = 0; tStep <= 48; tStep += 1) {
      const t = THREE.MathUtils.lerp(0.2, 0.98, tStep / 48);
      for (let uStep = 0; uStep <= 40; uStep += 1) {
        const u = THREE.MathUtils.lerp(-0.8, 0.8, uStep / 40);
        const projected = strandSplitControlPoint(
          lock,
          { position: u, height: 1 - t },
          t,
          curve,
          profileData
        ).project(camera);
        if (projected.z < -1 || projected.z > 1) continue;
        const x = (projected.x * 0.5 + 0.5) * rect.width;
        const y = (-projected.y * 0.5 + 0.5) * rect.height;
        const distanceSq = (x - targetX) ** 2 + (y - targetY) ** 2;
        if (!best || distanceSq < best.distanceSq) best = { distanceSq, position: u, height: 1 - t };
      }
    }
    if (!best) return;
    lock.strandSplitPosition = THREE.MathUtils.clamp(best.position, -0.8, 0.8);
    lock.strandSplitHeight = THREE.MathUtils.clamp(best.height, 0.02, 0.8);
    updateLockGeometry(lock, { immediate: true });
    updateCurveObjects(lock, { visible: true });
    syncActiveMirror(lock, { deferGeometry: false });
    updateTopologyStats();
    event.preventDefault();
    return;
  }
  for (let tStep = 0; tStep <= 42; tStep += 1) {
    const t = THREE.MathUtils.lerp(0.22, 1, tStep / 42);
    for (let uStep = 0; uStep <= 48; uStep += 1) {
      const u = THREE.MathUtils.lerp(-0.88, 0.88, uStep / 48);
      const projected = panelSplitControlPoint(lock, { position: u, height: 1 - t }, t, curve).project(camera);
      if (projected.z < -1 || projected.z > 1) continue;
      const x = (projected.x * 0.5 + 0.5) * rect.width;
      const y = (-projected.y * 0.5 + 0.5) * rect.height;
      const distanceSq = (x - targetX) ** 2 + (y - targetY) ** 2;
      if (!best || distanceSq < best.distanceSq) best = { distanceSq, position: u, height: 1 - t };
    }
  }
  if (!best) return;
  const splits = clonePanelSplits(lock.panelSplits, lock.panelSplitHeight, Math.max(0, Number(lock.panelWidthLoops ?? 6) - 1));
  const index = panelSplitDrag.splitIndex;
  if (!splits[index]) return;
  const minimumSeparation = Math.min(0.12, 0.8 / Math.max(3, Number(lock.panelWidthLoops ?? 6)));
  const minPosition = index > 0 ? splits[index - 1].position + minimumSeparation : -0.88;
  const maxPosition = index < splits.length - 1 ? splits[index + 1].position - minimumSeparation : 0.88;
  splits[index].position = THREE.MathUtils.clamp(best.position, minPosition, maxPosition);
  let nextHeight = best.height < 0.018 ? 0 : THREE.MathUtils.clamp(best.height, 0, 0.78);
  if (lock.panelSplitSnapToLoops !== false) {
    nextHeight = snapPanelSplitHeight(nextHeight, lock.panelLengthLoops);
  }
  splits[index].height = nextHeight;
  lock.panelSplits = splits;
  updateLockGeometry(lock, { immediate: true });
  updateCurveObjects(lock, { visible: true });
  syncActiveMirror(lock, { deferGeometry: false });
  updateTopologyStats();
  event.preventDefault();
}

function endPanelSplitHandleDrag(event) {
  if (!panelSplitDrag || (event?.pointerId !== undefined && event.pointerId !== panelSplitDrag.pointerId)) return;
  const { pointerId, lockId, kind } = panelSplitDrag;
  panelSplitDrag = null;
  if (renderer.domElement.hasPointerCapture?.(pointerId)) renderer.domElement.releasePointerCapture(pointerId);
  renderer.domElement.style.cursor = "";
  if (kind === "compound") flushPendingLockGeometryUpdates();
  const lock = locks.find((item) => item.id === lockId);
  if (lock) updateCurveObjects(lock, { visible: lock.id === selectedId });
  updateInteractionLocks();
}

