renderer.domElement.addEventListener("pointerdown", (event) => {
  if (proportionalSizeEdit || proportionalHotkeyPress) return;
  lastPointer.x = event.clientX;
  lastPointer.y = event.clientY;
  const rect = renderer.domElement.getBoundingClientRect();
  pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(pointer, camera);
  if (pointerHitsTransformGizmo(event)) return;
  const referenceSelectionActive = selectionToolSupportsPicking() && viewportEditMode === "reference";
  const referenceTransformActive = !referenceImagePanel.classList.contains("hidden")
    && ["move", "scale"].includes(activeTool);
  if (
    (referenceSelectionActive || referenceTransformActive)
    && event.button === 0
    && !event.shiftKey
    && !event.ctrlKey
    && !event.altKey
    && !event.metaKey
  ) {
    const overlayReference = viewportEditMode === "reference" ? referenceOverlayAtPointer(event) : null;
    if (overlayReference) {
      selectReferenceImage(overlayReference.id);
      if (["select", "move", "scale"].includes(activeTool)) {
        beginReferenceOverlayDrag(event, overlayReference);
      }
      event.preventDefault();
      return;
    }
    const referenceHit = referencePlaneHitFromPointer({
      ignoreOcclusion: viewportEditMode === "reference"
    });
    if (referenceHit?.object?.userData.referenceImageId) {
      selectReferenceImage(referenceHit.object.userData.referenceImageId);
      event.preventDefault();
      return;
    }
    if (referenceSelectionActive) {
      selectReferenceImage(null);
      event.preventDefault();
      return;
    }
  }
  if (scalpBuilderEditing) {
    if (event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) return;
    if (beginScalpBuilderInput(event)) event.preventDefault();
    return;
  }
  if (scalpPaintEditing) {
    if (event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) return;
    const scalpHit = raycaster.intersectObject(activeScalpSurfaceMesh(), false)[0];
    if (scalpHit) {
      beginScalpPaint(event, scalpHit);
      event.preventDefault();
    }
    return;
  }
  if (scalpLatticeEditing) {
    if (event.shiftKey || event.ctrlKey || event.altKey || event.metaKey || transformControls.axis) return;
    const latticeHit = raycaster.intersectObjects(scalpLatticeHandles, false)[0];
    if (latticeHit) {
      selectScalpLatticePoint(latticeHit.object.userData.scalpLatticeIndex);
      beginScalpLatticeDrag(latticeHit.object, event);
      event.preventDefault();
    } else if (transformControls.object?.userData.scalpLatticeIndex !== undefined) {
      transformControls.detach();
      selectedScalpLatticeIndex = null;
      scalpLatticeHandles.forEach((handle) => {
        handle.material.color.set(0x58f6ff);
        handle.material.opacity = 0.64;
      });
    }
    return;
  }
  if (scalpShapeEditing) return;
  if (selectHairShellFaceAtEvent(event)) {
    event.preventDefault();
    return;
  }
  if (beginPanelSplitHandleDrag(event)) {
    event.preventDefault();
    return;
  }
  if (activeTool === "draw-capsule-guide") {
    if (event.ctrlKey || event.altKey || event.metaKey) return;
    beginCapsuleGuideDrawStroke(event, drawSurfaceHitFromEvent(event, { root: true }));
    return;
  }
  if (capsuleGuideEditing) {
    if (!event.shiftKey && !event.ctrlKey && !event.altKey && !event.metaKey) {
      const guide = getSelectedGuide();
      const pointHit = guide?.type === "capsule" && guide.handlesGroup?.visible
        ? raycaster.intersectObjects(guide.handlesGroup.children.filter((handle) => handle.visible), false)[0]
        : null;
      const surfaceHit = guide?.type === "capsule" ? raycaster.intersectObject(guide.mesh, false)[0] : null;
      if (pointHit && (!surfaceHit || pointHit.distance <= surfaceHit.distance + 0.05)) {
        selectCapsuleGuidePoint(guide, pointHit.object.userData.capsuleGuidePointIndex);
        event.preventDefault();
        return;
      }
      if (beginCapsuleGuideLoopDrag(event)) {
        event.preventDefault();
        return;
      }
      const capsuleHit = raycaster.intersectObjects(
        guides
          .filter((item) => item.type === "capsule" && item.mesh.visible !== false)
          .map((item) => item.mesh),
        false
      )[0] || null;
      const capsuleGuideId = capsuleHit?.object?.userData?.guideId;
      if (capsuleGuideId && capsuleGuideId !== selectedGuideId) {
        selectGuide(capsuleGuideId);
        event.preventDefault();
        return;
      }
    }
    return;
  }
  if (["draw", "procedural-draw", "braid", "panel"].includes(activeTool)) {
    if (event.ctrlKey || event.altKey || event.metaKey) return;
    const extensionLock = selectedTipContinuationLock(event);
    const selectedLock = getSelectedLock();
    const drawingHairShell = activeTool === "draw" && selectedLock?.geometryType === "hair-shell";
    const hairShellStart = extensionLock ? null : selectedHairShellFaceStart(event);
    const branchStart = extensionLock
      ? null
      : hairShellStart || (!drawingHairShell ? selectedDrawBranchPoint(event) : null);
    const surfaceHit = extensionLock || branchStart || drawingHairShell
      ? null
      : drawSurfaceHitFromEvent(event, { root: true });
    beginDrawStrandStroke(event, surfaceHit, extensionLock, branchStart);
    return;
  }
  if (activeTool === "curve-surface") {
    if (event.ctrlKey || event.altKey || event.metaKey) return;
    const surfaceMode = activeStrokeSurfaceValue();
    const dynamicContextual = activeStrokeDynamicEnabled(surfaceMode);
    const hit = drawSurfaceHitFromEvent(event, { root: true })
      || (curveSurfaceDraft?.curves?.length
        ? curveSurfaceFallbackHit(event, surfaceMode, dynamicContextual)
        : null);
    beginCurveSurfaceStroke(event, hit);
    return;
  }
  if (activeTool === "surface-loft") {
    if (event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) return;
    beginLoftSurfaceStroke(event, drawSurfaceHitFromEvent(event, { root: true }));
    return;
  }
  if (activeTool === "place") {
    if (event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) return;
    if (placeEdit) {
      beginPlacementPointer(event);
      return;
    }
    const pendingLock = pendingPlacedLock();
    if (pendingPlacedLockId && !pendingLock) {
      finishPlacementFlow();
    } else if (pendingLock) {
      finishPlacementFlow({ keepSelected: true });
      return;
    }
    const curveLattice = selectedCurveLatticeGuide();
    const surfaceHit = curveLattice
      ? raycaster.intersectObjects([curveLattice.mesh, curveLattice.rootMesh].filter((object) => object && object.visible !== false), false)[0]
      : raycaster.intersectObject(activeScalpSurfaceMesh(), false)[0];
    beginPlacementPointer(event, surfaceHit);
    return;
  }
  if (selectionToolSupportsPicking()) {
    const addingSelection = event.shiftKey && !event.ctrlKey && !event.altKey && !event.metaKey;
    const removingSelection = event.ctrlKey && !event.shiftKey && !event.altKey && !event.metaKey;
    if (event.button === 0 && (addingSelection || removingSelection) && viewportEditMode === "strand") {
      const lockHit = raycaster.intersectObjects(
        locks.filter(strandAvailableForViewportInteraction).map((lock) => lock.mesh),
        false
      )[0] || null;
      const lockId = lockHit?.object?.userData.lockId;
      const selectedSurface = lockHit ? { type: "strand", hit: lockHit } : null;
      beginSelectionMarquee(event, selectedSurface, addingSelection ? "add" : "remove");
      event.preventDefault();
      return;
    }
    if (event.altKey || event.shiftKey || event.ctrlKey || event.metaKey) return;
    const selectingStrands = viewportEditMode === "strand";
    const selectingGuides = viewportEditMode === "guide";
    const curveSurfaceControllerHit = selectingStrands && componentEditModeActive()
      ? curveSurfaceControllerHitFromEvent(event)
      : null;
    if (curveSurfaceControllerHit) {
      selectionMarqueeDrag = null;
      selectLock(curveSurfaceControllerHit.lock.id, {
        individualClumpMember: true,
        curveSurfaceControllerIndex: curveSurfaceControllerHit.controllerIndex
      });
      event.preventDefault();
      return;
    }
    const selectedSurfaceLock = selectingStrands
      && componentEditModeActive()
      && getSelectedLock()?.geometryType === "surface"
      ? getSelectedLock()
      : null;
    const surfaceAnchorHandle = selectedSurfaceLock?.curveObjects?.surfaceObjectAnchorHandle;
    const surfaceAnchorHit = surfaceAnchorHandle && surfaceAnchorHandle.visible !== false
      ? raycaster.intersectObject(surfaceAnchorHandle, false)[0]
      : null;
    if (surfaceAnchorHit) {
      selectionMarqueeDrag = null;
      selectSurfaceObjectAnchor(selectedSurfaceLock, activeTool !== "select");
      event.preventDefault();
      return;
    }
    const selectedLattice = selectingGuides && componentEditModeActive()
      ? selectedCurveLatticeGuide()
      : null;
    const latticePointHit = selectedLattice?.handlesGroup.visible
      ? raycaster.intersectObjects(selectedLattice.handlesGroup.children, false)[0]
      : null;
    if (latticePointHit) {
      selectionMarqueeDrag = null;
      selectCurveLatticePoint(selectedLattice, latticePointHit.object.userData.curveLatticePointIndex, false);
      return;
    }
    const latticeLoopHit = curveLatticeLoopHitFromEvent(event, selectedLattice);
    if (latticeLoopHit && selectCurveLatticeLoop(
      selectedLattice,
      latticeLoopHit.axis,
      latticeLoopHit.loopIndex
    )) {
      selectionMarqueeDrag = null;
      event.preventDefault();
      return;
    }
    const lockHit = selectingStrands
      ? raycaster.intersectObjects(
        locks.filter(strandAvailableForViewportInteraction).map((lock) => lock.mesh),
        false
      )[0] || null
      : null;
    const guideHit = selectingGuides
      ? raycaster.intersectObjects(
        guides.flatMap((guide) => [guide.mesh, guide.rootMesh]
          .filter((object) => object && object.visible !== false)),
        false
      )[0] || null
      : null;
    const selectedSurface = guideHit
      ? { type: "guide", hit: guideHit }
      : lockHit
        ? { type: "strand", hit: lockHit }
        : null;
    if (beginSelectionMarquee(event, selectedSurface)) event.preventDefault();
    return;
  }

  const modelingClick = event.button === 0 && !event.shiftKey && !event.ctrlKey && !event.altKey && !event.metaKey;
  const selectedLattice = viewportEditMode === "guide" ? selectedCurveLatticeGuide() : null;
  if (modelingClick && activeTool === "move" && selectedLattice?.handlesGroup.visible) {
    const latticePointHit = raycaster.intersectObjects(selectedLattice.handlesGroup.children, false)[0];
    if (latticePointHit) {
      const directMove = activeTool === "move" && viewPlaneMoveActiveForView();
      const pointIndex = latticePointHit.object.userData.curveLatticePointIndex;
      const preserveMulti = selectedControlPoints.length > 1
        && controlPointIsSelected("lattice", selectedLattice.id, pointIndex);
      selectCurveLatticePoint(
        selectedLattice,
        pointIndex,
        !directMove,
        preserveMulti
      );
      if (directMove) beginViewPlaneMove(null, latticePointHit.object, event);
      event.preventDefault();
      return;
    }
    const latticeLoopHit = curveLatticeLoopHitFromEvent(event, selectedLattice);
    if (latticeLoopHit && selectCurveLatticeLoop(
      selectedLattice,
      latticeLoopHit.axis,
      latticeLoopHit.loopIndex
    )) {
      event.preventDefault();
      return;
    }
  }
  const selectedLock = viewportEditMode === "strand" ? getSelectedLock() : null;
  const curveSurfaceControllerHit = modelingClick
    ? curveSurfaceControllerHitFromEvent(event, selectedLock)
    : null;
  if (curveSurfaceControllerHit) {
    selectLock(curveSurfaceControllerHit.lock.id, {
      individualClumpMember: true,
      curveSurfaceControllerIndex: curveSurfaceControllerHit.controllerIndex
    });
    event.preventDefault();
    return;
  }
  const surfaceAnchorHandle = selectedLock?.geometryType === "surface"
    ? selectedLock.curveObjects?.surfaceObjectAnchorHandle
    : null;
  const surfaceAnchorHit = modelingClick && surfaceAnchorHandle && surfaceAnchorHandle.visible !== false
    ? raycaster.intersectObject(surfaceAnchorHandle, false)[0]
    : null;
  if (surfaceAnchorHit) {
    selectSurfaceObjectAnchor(selectedLock);
    event.preventDefault();
    return;
  }
  const handles = selectedLock?.curveObjects?.group.visible ? selectedLock.curveObjects.handles : [];
  const hit = modelingClick ? strandControlPointHitFromEvent(event, selectedLock) : null;

  if (!hit && modelingClick && ["move", "rotate", "scale"].includes(activeTool)) {
    const lockHit = viewportEditMode === "strand"
      ? raycaster.intersectObjects(
        locks.filter(strandAvailableForViewportInteraction).map((lock) => lock.mesh),
        false
      )[0] || null
      : null;
    const guideHit = viewportEditMode === "guide"
      ? raycaster.intersectObjects(
        guides.flatMap((guide) => [guide.mesh, guide.rootMesh]
          .filter((object) => object && object.visible !== false)),
        false
      )[0] || null
      : null;
    const selectedSurface = guideHit
      ? { type: "guide", hit: guideHit }
      : lockHit
        ? { type: "strand", hit: lockHit }
        : null;

    if (selectedSurface?.type === "guide") {
      const guideId = selectedSurface.hit.object.userData.guideId;
      if (guideId && guideId !== selectedGuideId) {
        selectGuide(guideId);
        event.preventDefault();
        return;
      }
    } else if (selectedSurface?.type === "strand") {
      const lockId = selectedSurface.hit.object.userData.lockId;
      if (lockId && lockId !== selectedId) {
        selectLock(lockId);
        event.preventDefault();
        return;
      }
    }
  }

  if (!hit) {
    if (modelingClick && activeTool === "relax" && selectedLock && selectedPoint?.lockId === selectedLock.id) {
      if (beginRelaxEdit(selectedLock, selectedPoint.pointIndex, event)) {
        event.preventDefault();
      }
    }
    return;
  }
  activateStrandControlPoint(hit.object, event);
});

let fpsFrameCount = 0;
let fpsSampleStart = performance.now();
let previousAnimationTimestamp = performance.now();

function animate(timestamp = performance.now()) {
  const deltaSeconds = Math.min(0.1, Math.max(0, (timestamp - previousAnimationTimestamp) / 1000));
  previousAnimationTimestamp = timestamp;
  fpsFrameCount += 1;
  const fpsElapsed = timestamp - fpsSampleStart;
  if (fpsElapsed >= 500) {
    viewportFps.textContent = `${Math.round((fpsFrameCount * 1000) / fpsElapsed)} FPS`;
    fpsFrameCount = 0;
    fpsSampleStart = timestamp;
  }
  if (turntableActive && !altOrbitDrag && !viewSnapDrag) {
    const cameraOffset = camera.position.clone().sub(controls.target);
    cameraOffset.applyAxisAngle(
      turntableAxis,
      TURNTABLE_RADIANS_PER_SECOND * turntableSpeed * deltaSeconds
    );
    camera.position.copy(controls.target).add(cameraOffset);
    camera.lookAt(controls.target);
  }
  controls.update();
  updateCameraViewCube();
  updateSculptBrushViabilityPlane();
  updateReferencePlaneVisibility();
  updateReferenceCropHandles();
  updateViewPlaneGrid();
  updatePullGuideVisual();
  renderUvInspector(timestamp);
  refreshShadowMapWhenIdle(timestamp);
  renderer.render(scene, camera);
  if (multiCameraEnabled && multiCameraPreviewRenderers) {
    syncMultiCameraPreviewCameras();
    renderNextInactiveMultiCameraPreview();
  }
  requestAnimationFrame(animate);
}

let compactOutlinerCollapsed = false;
let compactAttributeEditorCollapsed = false;

function syncCompactSidebarLayout() {
  document.body.classList.toggle("compact-outliner-collapsed", compactOutlinerCollapsed);
  document.body.classList.toggle("compact-attribute-collapsed", compactAttributeEditorCollapsed);

  toggleOutlinerPanelButton.setAttribute("aria-expanded", String(!compactOutlinerCollapsed));
  toggleOutlinerPanelButton.title = compactOutlinerCollapsed ? "Expand outliner" : "Collapse outliner";
  toggleOutlinerPanelButton.setAttribute("aria-label", toggleOutlinerPanelButton.title);
  toggleOutlinerPanelButton.querySelector("span").textContent = compactOutlinerCollapsed ? "\u2304" : "\u2303";

  toggleAttributeEditorPanelButton.setAttribute("aria-expanded", String(!compactAttributeEditorCollapsed));
  toggleAttributeEditorPanelButton.title = compactAttributeEditorCollapsed
    ? "Expand attribute editor"
    : "Collapse attribute editor";
  toggleAttributeEditorPanelButton.setAttribute("aria-label", toggleAttributeEditorPanelButton.title);
  toggleAttributeEditorPanelButton.querySelector("span").textContent = compactAttributeEditorCollapsed ? "\u2304" : "\u2303";

  window.requestAnimationFrame(resize);
}

function setOutlinerPanelCollapsed(collapsed) {
  compactOutlinerCollapsed = Boolean(collapsed);
  if (compactOutlinerCollapsed) compactAttributeEditorCollapsed = false;
  syncCompactSidebarLayout();
}

function setAttributeEditorPanelCollapsed(collapsed) {
  compactAttributeEditorCollapsed = Boolean(collapsed);
  if (compactAttributeEditorCollapsed) compactOutlinerCollapsed = false;
  syncCompactSidebarLayout();
}

function setAttributeEditorTab(tabName) {
  const activeTab = ["main", "display", "materials"].includes(tabName) ? tabName : "main";
  toolPanel.dataset.activeAttributeTab = activeTab;
  attributeEditorTabs.forEach((button) => {
    const selected = button.dataset.attributeTab === activeTab;
    button.classList.toggle("active", selected);
    button.setAttribute("aria-selected", String(selected));
    button.tabIndex = selected ? 0 : -1;
  });
  attributeEditorPanels.forEach((panel) => {
    const assignedTab = panel.dataset.attributePanel || "main";
    const panelTab = ["tools", "strands"].includes(assignedTab) ? "main" : assignedTab;
    panel.classList.toggle("attribute-tab-hidden", panelTab !== activeTab);
  });
  updateStrandSelectionHighlight();
}

attributeEditorTabs.forEach((button, index) => {
  button.addEventListener("click", () => {
    setAttributeEditorPanelCollapsed(false);
    setAttributeEditorTab(button.dataset.attributeTab);
  });
  button.addEventListener("keydown", (event) => {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    let nextIndex = index;
    if (event.key === "ArrowLeft") nextIndex = (index - 1 + attributeEditorTabs.length) % attributeEditorTabs.length;
    if (event.key === "ArrowRight") nextIndex = (index + 1) % attributeEditorTabs.length;
    if (event.key === "Home") nextIndex = 0;
    if (event.key === "End") nextIndex = attributeEditorTabs.length - 1;
    const nextTab = attributeEditorTabs[nextIndex];
    setAttributeEditorTab(nextTab.dataset.attributeTab);
    nextTab.focus();
  });
});

toggleOutlinerPanelButton.addEventListener("click", () => {
  setOutlinerPanelCollapsed(!compactOutlinerCollapsed);
});
toggleAttributeEditorPanelButton.addEventListener("click", () => {
  setAttributeEditorPanelCollapsed(!compactAttributeEditorCollapsed);
});

setAttributeEditorTab("main");
syncCompactSidebarLayout();
loadCustomHairMaterialPresets();
populateHairMaterialPresetSelect();
syncHairMaterialEditor();
renderLockList();
updateAttributeEditorMode();
setSideNamingPerspective(sideNamingPerspective, { persist: false });
resize();
animate();
offerRecoverySnapshot();
